import { validate, ValidationResult } from './validator';
import { filterLargeList, normalizeScores } from './processor';
import { runPipeline, PipelineState } from './pipeline';

// --- Tests for validator.ts ---
async function testValidator() {
  console.log("--- Running Validator Tests ---");

  // Test 1: Basic valid object
  const schema1 = { required: ['a', 'b'] };
  const data1 = { a: 1, b: 'test' };
  const result1 = validate(data1, schema1);
  console.assert(result1.valid === true, `Test 1 Failed: Expected valid=true, got ${result1.valid}`);

  // Test 2: Missing required field
  const schema2 = { required: ['a', 'c'] };
  const data2 = { a: 1, b: 'test' };
  const result2 = validate(data2, schema2);
  console.assert(result2.valid === false && result2.errors.includes("Missing required field: c"), `Test 2 Failed: Expected missing field error for 'c', got ${result2.errors}`);

  // Test 3: Input is null
  const schema3 = { required: ['a'] };
  const result3 = validate(null, schema3);
  console.assert(result3.valid === false && result3.errors[0] === "Input must be an object", `Test 3 Failed: Expected null input error, got ${result3.errors}`);

  // Test 4: Falsy but valid values (BUG FIX verification)
  const schema4 = { required: ['zero', 'empty', 'falsey'] };
  const data4 = { zero: 0, empty: "", falsey: false };
  const result4 = validate(data4, schema4);
  console.assert(result4.valid === true, `Test 4 Failed: Expected valid=true for falsy values, got ${result4.valid}`);
}

// --- Tests for processor.ts ---
async function testProcessor() {
  console.log("--- Running Processor Tests ---");

  // Test 5: List size < 10 (should return original list)
  const items5 = [1, 2, 3];
  const result5 = filterLargeList(items5, () => true);
  console.assert(result5.length === 3, `Test 5 Failed: Expected original list length 3, got ${result5.length}`);

  // Test 6: List size >= 10 (should filter)
  const items6 = Array(12).fill(1);
  const predicate6 = (item: number) => item === 1;
  const result6 = filterLargeList(items6, predicate6);
  console.assert(result6.length === 12, `Test 6 Failed: Expected filtered list length 12, got ${result6.length}`);

  // Test 7: Normalization (basic)
  const scores7 = [1, 2, 4];
  const expected7 = [0.25, 0.5, 1.0];
  const result7 = normalizeScores(scores7);
  console.assert(result7.length === 3 && Math.abs(result7[0] - expected7[0]) < 0.001, `Test 7 Failed: Normalization failed. Got ${result7}`);

  // Test 8: Normalization (all zeros)
  const scores8 = [0, 0, 0];
  const expected8 = [0, 0, 0];
  const result8 = normalizeScores(scores8);
  console.assert(result8.length === 3 && result8.every(s => s === 0), `Test 8 Failed: Normalization of zeros failed. Got ${result8}`);
}

// --- Tests for pipeline.ts ---
async function testPipeline() {
  console.log("--- Running Pipeline Tests ---");

  // Test 9: Sequential execution verification (BUG FIX verification)
  const initialState = { count: 0, results: [] };
  const results9 = await runPipeline(initialState);

  // Since we fixed the concurrency issue, the count should increment sequentially:
  // processFirst runs first (count=1), then processSecond runs (count=1).
  // Wait, looking at the fixed code:
  // 1. r1 = await processFirst(state) -> state.count = 1. r1 = "first-1"
  // 2. r2 = await processSecond(state) -> state.count = 1. r2 = "second-1"
  // This confirms sequential execution and state visibility.
  const expected9 = ["first-1", "second-1"];
  console.assert(results9.length === 2 && results9[0] === expected9[0] && results9[1] === expected9[1], `Test 9 Failed: Pipeline execution failed. Got ${results9}`);
}

async function runAllTests() {
  await testValidator();
  await testProcessor();
  await testPipeline();
  console.log("\nAll tests completed.");
}

runAllTests();

